mapper.select:
SELECT payment_pin_hash, pin_fail_count
FROM users
WHERE user_id = #{userId}

mapper.update:
UPDATE users
SET pin_fail_count = pin_fail_count + 1
WHERE user_id = #{userId}

mapper.select:
SELECT pin_auth_id, auth_expires_at, auth_is_used
FROM users
WHERE user_id = #{userId}

SELECT EXISTS (
SELECT 1 FROM user_card
WHERE user_card_id = #{userCardId}
AND user_id = #{userId}
AND is_deleted = 0
)

mapper.update:
UPDATE users
SET auth_is_used = 1
WHERE user_id = #{userId}

mapper.select:
SELECT ps.status, ps.payment_id, ps.expires_at, ps.created_at
FROM payment_session ps
JOIN user_card uc ON uc.user_card_id = ps.user_card_id
WHERE ps.session_token = #{qrToken}
AND uc.user_id = #{userId}
AND uc.is_deleted = 0

mapper.update:
UPDATE payment_session
SET status = 'SCANNED',
payment_id = #{paymentId}
WHERE session_token = #{qrToken}

UPDATE payment_session
SET status = 'EXPIRED'
WHERE session_token = #{qrToken}

mapper.select:
SELECT ps.payment_session_id, ps.status, ps.store_id, ps.amount, ps.user_card_id, ps.updated_at, ps.expires_at, ps.fail_reason
FROM payment_session ps
JOIN user_card uc ON uc.user_card_id = ps.user_card_id
WHERE ps.payment_id = #{paymentId}
AND uc.user_id = #{userId}
AND uc.is_deleted = 0

mapper.update:
UPDATE payment_session
SET status = 'PROCESSING',
store_id = #{storeId},
amount = #{amount}
WHERE payment_id = #{paymentId}

UPDATE payment_session
SET status = 'COMPLETED'
WHERE payment_id = #{paymentId}

mapper.select:
SELECT store_id, store_name
FROM store
WHERE store_qr_token = #{storeQrToken}
